
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_24_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_24", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.217362496160551e+00, -5.117303184150253e+00, -4.976853327554902e+00, -4.781723955911538e+00, -4.514426344475529e+00, -4.155000999513849e+00, -3.682245668479159e+00, -3.073071376554594e+00, -2.301342115994660e+00, -1.420134808733994e+00, -7.718514519035414e-01, -5.870069006509984e-01, -6.390619705729713e-01, -5.512171532617924e-01, -3.576542964168332e-01, -1.716951679755422e-01, -6.664389884504113e-02, -2.118292269100400e-02, -4.507063209474292e-03, -5.057754382697164e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


